-- Phase 1 schema: PRD.md section 5.4, limited to the Phase 1 tables.
-- Changes from the PRD are recorded in docs/DECISIONS.md (D-003, D-004):
--   * stores.owner_id is unique (one store per creator)
--   * default theme accent is #2F3BFF (DESIGN.md Clean preset)
--   * products: no order-bump columns (Phase 2), type defaults to 'digital', pwyw needs a minimum
--   * order_items: no is_bump column (Phase 2)
--   * enrollments.download_count added
--   * money columns are integer cents with non-negative checks
-- RLS, grants and views are in the next migration. Do not edit this file once pushed.

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------

create or replace function public.set_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
  new.updated_at := now();
  return new;
end;
$$;

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  email text not null,
  full_name text,
  -- Set only by the stores insert trigger, never by the client (D-003).
  role text not null default 'buyer' check (role in ('creator', 'buyer')),
  created_at timestamptz not null default now()
);

create table public.stores (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null unique references public.profiles (id) on delete cascade,
  slug text not null unique check (slug ~ '^[a-z0-9-]{3,30}$'),
  custom_domain text unique,
  name text not null,
  bio text,
  avatar_url text,
  theme jsonb not null default '{"preset":"clean","accent":"#2F3BFF"}',
  social_links jsonb not null default '[]',
  currency text not null default 'usd' check (currency in ('usd', 'gbp', 'cad')),
  -- Written only by the service role (Stripe OAuth callback and Connect webhook).
  stripe_account_id text unique,
  stripe_charges_enabled boolean not null default false,
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.products (
  id uuid primary key default gen_random_uuid(),
  store_id uuid not null references public.stores (id) on delete cascade,
  type text not null default 'digital' check (type in ('course', 'digital')),
  title text not null,
  slug text not null,
  description text,
  cover_url text,
  price_cents integer not null check (price_cents >= 0),
  compare_at_price_cents integer check (compare_at_price_cents >= 0),
  pricing_model text not null default 'fixed' check (pricing_model in ('fixed', 'pwyw')),
  min_price_cents integer check (min_price_cents >= 0),
  download_limit integer check (download_limit > 0),
  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),
  sort_order integer not null default 0,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (store_id, slug),
  constraint products_pwyw_requires_min check (pricing_model <> 'pwyw' or min_price_cents is not null)
);

create table public.product_files (
  id uuid primary key default gen_random_uuid(),
  product_id uuid not null references public.products (id) on delete cascade,
  -- Private bucket path. Never exposed publicly; downloads use short-lived signed URLs.
  storage_path text not null,
  file_name text not null,
  size_bytes bigint not null check (size_bytes >= 0),
  mime_type text,
  position integer not null default 0,
  created_at timestamptz not null default now()
);

create table public.orders (
  id uuid primary key default gen_random_uuid(),
  store_id uuid not null references public.stores (id) on delete cascade,
  buyer_user_id uuid references public.profiles (id) on delete set null,
  buyer_email text not null,
  status text not null default 'pending' check (status in ('pending', 'paid', 'refunded', 'failed')),
  subtotal_cents integer not null check (subtotal_cents >= 0),
  discount_cents integer not null default 0 check (discount_cents >= 0),
  total_cents integer not null check (total_cents >= 0),
  currency text not null check (currency in ('usd', 'gbp', 'cad')),
  stripe_checkout_session_id text unique,
  stripe_payment_intent_id text,
  created_at timestamptz not null default now()
);

create table public.order_items (
  id uuid primary key default gen_random_uuid(),
  order_id uuid not null references public.orders (id) on delete cascade,
  product_id uuid not null references public.products (id),
  unit_price_cents integer not null check (unit_price_cents >= 0)
);

create table public.enrollments (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references public.profiles (id) on delete cascade,
  product_id uuid not null references public.products (id) on delete cascade,
  order_id uuid references public.orders (id) on delete set null,
  download_count integer not null default 0 check (download_count >= 0),
  revoked_at timestamptz,
  created_at timestamptz not null default now(),
  unique (user_id, product_id)
);

create table public.webhook_events (
  id text primary key, -- provider event id (idempotency key)
  source text not null check (source in ('stripe-platform', 'stripe-connect', 'mux')),
  type text not null,
  payload jsonb not null,
  processed_at timestamptz,
  created_at timestamptz not null default now()
);

create table public.email_log (
  id uuid primary key default gen_random_uuid(),
  store_id uuid references public.stores (id) on delete set null,
  to_email text not null,
  template text not null,
  status text not null default 'queued',
  provider_id text,
  created_at timestamptz not null default now()
);

-- ---------------------------------------------------------------------------
-- Indexes (foreign keys used by RLS policies and dashboard queries)
-- ---------------------------------------------------------------------------

create index products_store_id_idx on public.products (store_id);
create index product_files_product_id_idx on public.product_files (product_id);
create index orders_store_id_idx on public.orders (store_id);
create index orders_buyer_user_id_idx on public.orders (buyer_user_id);
create index orders_payment_intent_idx on public.orders (stripe_payment_intent_id);
create index order_items_order_id_idx on public.order_items (order_id);
create index order_items_product_id_idx on public.order_items (product_id);
create index enrollments_product_id_idx on public.enrollments (product_id);
create index enrollments_order_id_idx on public.enrollments (order_id);
create index email_log_store_id_idx on public.email_log (store_id);

-- ---------------------------------------------------------------------------
-- updated_at triggers
-- ---------------------------------------------------------------------------

create trigger stores_set_updated_at
  before update on public.stores
  for each row execute function public.set_updated_at();

create trigger products_set_updated_at
  before update on public.products
  for each row execute function public.set_updated_at();
